import math, re

def idf_table(docs):
    n_docs = len(docs)
    df = {}
    for d in docs:
        for t in set(re.findall(r'[a-z0-9]+', d.lower())):
            df[t] = df.get(t, 0) + 1
    return {t: round(math.log(1 + (n_docs - n + 0.5) / (n + 0.5)), 4) for t, n in df.items()}

