def rrf(rankings, k=60, top_n=None):
    scores = {}
    for ranking in rankings:
        seen = set()
        for rank, d in enumerate(ranking, start=1):
            if d in seen:
                continue
            seen.add(d)
            scores[d] = scores.get(d, 0.0) + 1 / (k + rank)
    ordered = sorted(scores, key=lambda d: (-scores[d], d))
    return ordered[:top_n] if top_n is not None else ordered
